-- 세트 525. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set525.sql, 05·06·08. docs/specs/spec_pilot_gap_sets.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 525, '데이터 모델링 기초 (1) 테이블 나누기와 관계: 엔티티·PK, 1:N 과 외래 키, N:M 과 연결 테이블', '테이블을 어떻게 나누고 어떻게 잇는지 배웁니다. 엔티티·속성·기본키, 1:N 관계와 외래 키, N:M 관계와 연결 테이블, 텍스트 ERD 읽기를 개념 문제와 직접 CREATE TABLE 실습으로 익힙니다.', 'linux-db', '데이터베이스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 525);
UPDATE quest_set SET display_order = 746, unit_id = (SELECT id FROM unit WHERE id = 46), icon = '🧩' WHERE id = 525;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 525, 1, '엔티티는 테이블 하나', '데이터 모델링은 "무엇을 어떤 테이블에 담을지" 정하는 일입니다. 쇼핑몰에서 **고객**, **주문**, **상품**처럼 업무에서 따로 관리하고 싶은 대상을 **엔티티**라고 부릅니다. 엔티티는 보통 DB 에서 무엇이 될까요?', '엔티티 하나를 담아 두는 곳입니다.', NULL, NULL, '[]', 'choice', '["열(컬럼) 하나", "데이터베이스 하나", "테이블 하나", "인덱스 하나"]', 2, '엔티티(고객·주문 등)는 보통 테이블 하나가 되고, 엔티티의 특징(이름·이메일 등)인 **속성**은 그 테이블의 열이 됩니다. 한 건의 실제 고객은 테이블의 행 하나입니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 525 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 525, 2, '기본키(PK)로 쓸 속성', '`customers`(고객) 테이블의 속성은 이름, 전화번호, 고객번호입니다. 행을 **하나씩 정확히 구분**하는 기본키(PK)로 가장 알맞은 것은 무엇일까요?', '중복되지 않고 시간이 지나도 바뀌지 않는 값을 찾아보세요.', NULL, NULL, '[]', 'choice', '["이름", "고객번호 (시스템이 붙인 번호)", "전화번호", "이름과 전화번호를 이어 붙인 글자"]', 1, '기본키는 **중복이 없고 바뀌지 않는** 값이어야 합니다. 이름은 동명이인이 있고, 전화번호는 바뀔 수 있습니다. 그래서 시스템이 붙이는 고객번호(`id`)를 쓰는 것이 일반적입니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 525 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 525, 3, '고객 테이블 만들기 (엔티티와 PK)', '`modeling` 데이터베이스가 비어 있습니다. **고객(`customers`) 테이블**을 만드세요. 열은 `id`(정수, 기본키), `name`(글자 20자), `email`(글자 40자) 입니다. 그다음 고객 **3명 이상**을 `INSERT` 하세요. 접속은 `mariadb modeling` 입니다.', '`CREATE TABLE` 에서 `id INT PRIMARY KEY` 처럼 열 옆에 기본키를 지정합니다. 값은 `INSERT INTO 테이블 VALUES (...)`, 여러 행은 쉼표로 잇습니다.', 'mariadb modeling -e ''CREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(20), email VARCHAR(40)); INSERT INTO customers VALUES (1,"kim","kim@example.com"),(2,"lee","lee@example.com"),(3,"park","park@example.com")''

# 엔티티 = 테이블, 속성 = 열, id 가 PK', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS modeling; CREATE DATABASE modeling;''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(mariadb -N modeling -e ''SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE WHERE table_schema=\\"modeling\\" AND table_name=\\"customers\\" AND constraint_name=\\"PRIMARY\\" AND column_name=\\"id\\"'')\\" = 1 ] ) && ( [ \\"$(mariadb -N modeling -e ''SELECT COUNT(*) FROM information_schema.COLUMNS WHERE table_schema=\\"modeling\\" AND table_name=\\"customers\\" AND column_name IN (\\"name\\",\\"email\\")'')\\" = 2 ] ) && ( [ \\"$(mariadb -N modeling -e ''SELECT COUNT(*) FROM customers'')\\" -ge 3 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "id 가 기본키다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N modeling -e ''SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE WHERE table_schema=\\"modeling\\" AND table_name=\\"customers\\" AND constraint_name=\\"PRIMARY\\" AND column_name=\\"id\\"'')\\" = 1 ]"]}, {"label": "name·email 열이 있다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N modeling -e ''SELECT COUNT(*) FROM information_schema.COLUMNS WHERE table_schema=\\"modeling\\" AND table_name=\\"customers\\" AND column_name IN (\\"name\\",\\"email\\")'')\\" = 2 ]"]}, {"label": "고객이 3명 이상이다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N modeling -e ''SELECT COUNT(*) FROM customers'')\\" -ge 3 ]"]}]', '[{"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 525 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 525, 4, '테이블을 나누는 이유', '주문 테이블 하나에 **주문 내용과 고객 이름·이메일을 모두** 적었습니다. 한 고객이 주문을 50번 하면 같은 이름·이메일이 50번 들어갑니다. 이때 생기는 가장 큰 문제는 무엇일까요?', '고객의 이메일이 바뀌는 상황을 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["주문 번호가 중복된다", "SELECT 가 실행되지 않는다", "기본키를 만들 수 없다", "이메일이 바뀌면 50개 행을 모두 고쳐야 하고, 하나라도 빠뜨리면 값이 서로 어긋난다"]', 3, '같은 정보를 여러 곳에 적으면 수정할 곳이 많아지고 불일치가 생깁니다. 고객 정보는 `customers` 에 한 번만 두고, 주문에는 어느 고객인지 **고객번호만** 적도록 테이블을 나눕니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 525 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 525, 5, '1:N 관계와 외래 키의 위치', '고객 한 명은 주문을 여러 건 할 수 있지만, 주문 한 건은 고객 한 명에게만 속합니다. 이런 **1:N(일대다)** 관계에서 고객번호를 가리키는 **외래 키(FK) 열**은 어느 테이블에 둘까요?', '주문 한 건이 고객 몇 명에게 속하는지, 고객 한 명이 주문 몇 건을 갖는지 각각 세어 보세요.', NULL, NULL, '[]', 'choice', '["1 쪽인 `customers` 테이블", "두 테이블 모두", "N 쪽인 `orders` 테이블", "어느 쪽이든 상관없다"]', 2, 'N 쪽(`orders`)의 각 행이 자기 부모(한 명의 고객)를 `customer_id` 로 가리킵니다. 1 쪽에 두면 한 칸에 주문 번호 여러 개를 넣어야 해서 표현할 수 없습니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 525 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 525, 6, '외래 키 선언', '`orders.customer_id` 가 `customers` 테이블의 `id` 를 가리키도록 외래 키를 선언하는 문장입니다. 빈칸을 채우세요.', '다른 테이블의 열을 근거로 삼는다는 뜻의 키워드입니다.', NULL, NULL, '[]', 'fill', '["REFERENCES", "LINKS", "JOIN", "POINTS"]', NULL, '`FOREIGN KEY (열) REFERENCES 부모테이블(열)` 형태입니다. 이렇게 선언하면 `customers` 에 없는 고객번호로는 주문을 넣을 수 없습니다.', '[0]', 'CREATE TABLE orders (id INT PRIMARY KEY, customer_id INT, FOREIGN KEY (customer_id) {0} customers(id));', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 525 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 525, 7, '주문 테이블 만들기 (1:N)', '`modeling` 데이터베이스(`mariadb modeling`)를 씁니다. `customers`(고객) 테이블이 이미 있습니다. **주문(`orders`) 테이블**을 만드세요. 열은 `id`(정수, 기본키), `customer_id`(정수), `item`(글자 30자) 이고, `customer_id` 는 `customers(id)` 를 가리키는 **외래 키**여야 합니다. 주문 **3건 이상**을 넣으세요(고객 1번이 2건 이상). 존재하지 않는 고객번호는 외래 키 때문에 들어가지 않습니다.', '`mariadb modeling` 으로 접속합니다. `CREATE TABLE` 마지막에 `FOREIGN KEY (...) REFERENCES ...(...)` 를 한 줄 더 적습니다. `SHOW CREATE TABLE orders\\G` 로 확인할 수 있습니다.', 'mariadb modeling -e ''CREATE TABLE orders (id INT PRIMARY KEY, customer_id INT, item VARCHAR(30), FOREIGN KEY (customer_id) REFERENCES customers(id)); INSERT INTO orders VALUES (1,1,"pen"),(2,1,"book"),(3,2,"desk")''

# N 쪽(orders)에 FK. 부모(customers)가 먼저 있어야 만들 수 있다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS modeling; CREATE DATABASE modeling;''; mariadb modeling -e ''CREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(20)); INSERT INTO customers VALUES (1,\\"kim\\"),(2,\\"lee\\"),(3,\\"park\\");''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(mariadb -N modeling -e ''SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE WHERE table_schema=\\"modeling\\" AND table_name=\\"orders\\" AND column_name=\\"customer_id\\" AND referenced_table_name=\\"customers\\" AND referenced_column_name=\\"id\\"'')\\" = 1 ] ) && ( [ \\"$(mariadb -N modeling -e ''SELECT COUNT(*) FROM orders'')\\" -ge 3 ] ) && ( [ \\"$(mariadb -N modeling -e ''SELECT COUNT(*) FROM (SELECT customer_id FROM orders GROUP BY customer_id HAVING COUNT(*) >= 2) t'')\\" -ge 1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "orders.customer_id 가 customers 를 참조한다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N modeling -e ''SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE WHERE table_schema=\\"modeling\\" AND table_name=\\"orders\\" AND column_name=\\"customer_id\\" AND referenced_table_name=\\"customers\\" AND referenced_column_name=\\"id\\"'')\\" = 1 ]"]}, {"label": "주문이 3건 이상이다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N modeling -e ''SELECT COUNT(*) FROM orders'')\\" -ge 3 ]"]}, {"label": "한 고객이 주문을 2건 이상 했다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N modeling -e ''SELECT COUNT(*) FROM (SELECT customer_id FROM orders GROUP BY customer_id HAVING COUNT(*) >= 2) t'')\\" -ge 1 ]"]}]', '[{"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 525 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 525, 8, '고객별 주문 건수 확인 (JOIN)', '`modeling` 데이터베이스(`mariadb modeling`)를 씁니다. `customers`(고객 3명)와 `orders`(주문)가 있습니다. **고객 이름과 그 고객의 주문 건수**를 `/tmp/count.txt` 에 저장하세요(제목 줄 없이). **주문이 한 건도 없는 고객도** 건수 0 으로 나와야 합니다.', '고객을 기준으로 `LEFT JOIN orders ON orders.customer_id = customers.id` 하고, 고객별로 `GROUP BY` 해 `orders` 쪽 열을 `COUNT` 합니다. `mariadb -N modeling -e "..."` 출력을 `>` 로 저장합니다.', 'mariadb -N modeling -e ''SELECT c.name, COUNT(o.id) FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.id, c.name'' > /tmp/count.txt
cat /tmp/count.txt

# 1:N 은 FK 로 JOIN 한다. 주문 없는 고객도 보려면 LEFT JOIN, COUNT 는 o.id 로 센다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS modeling; CREATE DATABASE modeling;''; mariadb modeling -e ''CREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(20)); INSERT INTO customers VALUES (1,\\"kim\\"),(2,\\"lee\\"),(3,\\"park\\"); CREATE TABLE orders (id INT PRIMARY KEY, customer_id INT, item VARCHAR(30), FOREIGN KEY (customer_id) REFERENCES customers(id)); INSERT INTO orders VALUES (1,1,\\"pen\\"),(2,1,\\"book\\"),(3,2,\\"desk\\");''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(grep -c . /tmp/count.txt)\\" = 3 ] ) && ( awk -F\\"\\\\t\\" ''$1==\\"kim\\" && $2==2'' /tmp/count.txt | grep -q . ) && ( awk -F\\"\\\\t\\" ''$1==\\"park\\" && $2==0'' /tmp/count.txt | grep -q . )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "3줄이다", "cmd": ["sh", "-c", "[ \\"$(grep -c . /tmp/count.txt)\\" = 3 ]"]}, {"label": "kim 은 2건이다", "cmd": ["sh", "-c", "awk -F\\"\\\\t\\" ''$1==\\"kim\\" && $2==2'' /tmp/count.txt | grep -q ."]}, {"label": "park 은 0건이다", "cmd": ["sh", "-c", "awk -F\\"\\\\t\\" ''$1==\\"park\\" && $2==0'' /tmp/count.txt | grep -q ."]}]', '[{"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 525 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 525, 9, 'N:M 관계는 외래 키 하나로 안 된다', '한 학생은 여러 강의를 들을 수 있고, 한 강의에는 여러 학생이 있습니다. 이런 **N:M(다대다)** 관계를 DB 에 표현하는 올바른 방법은 무엇일까요?', '`students` 에 열 하나를 넣으면 한 학생이 강의 하나만 가리키게 됩니다.', NULL, NULL, '[]', 'choice', '["`students` 테이블에 `course_id` 열 하나를 둔다", "`courses` 테이블에 `student_id` 열 하나를 둔다", "두 테이블 사이에 학생번호와 강의번호를 짝지어 적는 별도 테이블을 둔다", "`students` 의 한 칸에 강의 번호를 쉼표로 여러 개 적는다"]', 2, 'N:M 은 외래 키 열 하나로 나타낼 수 없어, 두 FK 를 가진 **연결 테이블**(예: `enrollments`)로 쪼갭니다. 쉼표로 여러 값을 한 칸에 넣으면 JOIN 도 외래 키도 쓸 수 없습니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 525 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 525, 10, '연결 테이블 만들기 (N:M)', '`modeling` 데이터베이스(`mariadb modeling`)를 씁니다. `students`(학생)와 `courses`(강의) 테이블이 있습니다. 수강 관계를 담는 **연결 테이블 `enrollments`** 를 만드세요. 열은 `student_id`, `course_id`(둘 다 정수)이고, 두 열이 각각 `students(id)`, `courses(id)` 를 가리키는 **외래 키**입니다. 같은 학생이 같은 강의를 두 번 등록하지 못하도록 **두 열을 묶어 기본키**(`PRIMARY KEY (student_id, course_id)`)로 지정하세요. 수강 기록 **3건 이상**을 넣으세요.', '`mariadb modeling` 으로 접속합니다. 외래 키 선언 두 줄과 `PRIMARY KEY (열1, 열2)` 한 줄을 `CREATE TABLE` 안에 적습니다. 두 열을 묶은 기본키는 짝이 같을 때만 중복으로 봅니다.', 'mariadb modeling -e ''CREATE TABLE enrollments (student_id INT, course_id INT, PRIMARY KEY (student_id, course_id), FOREIGN KEY (student_id) REFERENCES students(id), FOREIGN KEY (course_id) REFERENCES courses(id)); INSERT INTO enrollments VALUES (1,1),(1,2),(2,1)''

# N:M = 연결 테이블 + 외래 키 둘. 두 열 묶음 PK 로 같은 짝 중복을 막는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS modeling; CREATE DATABASE modeling;''; mariadb modeling -e ''CREATE TABLE students (id INT PRIMARY KEY, name VARCHAR(20)); INSERT INTO students VALUES (1,\\"kim\\"),(2,\\"lee\\"); CREATE TABLE courses (id INT PRIMARY KEY, title VARCHAR(30)); INSERT INTO courses VALUES (1,\\"sql\\"),(2,\\"linux\\");''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(mariadb -N modeling -e ''SELECT COUNT(DISTINCT referenced_table_name) FROM information_schema.KEY_COLUMN_USAGE WHERE table_schema=\\"modeling\\" AND table_name=\\"enrollments\\" AND referenced_table_name IN (\\"students\\",\\"courses\\")'')\\" = 2 ] ) && ( [ \\"$(mariadb -N modeling -e ''SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE WHERE table_schema=\\"modeling\\" AND table_name=\\"enrollments\\" AND constraint_name=\\"PRIMARY\\"'')\\" = 2 ] ) && ( [ \\"$(mariadb -N modeling -e ''SELECT COUNT(*) FROM enrollments'')\\" -ge 3 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "students·courses 를 각각 참조하는 외래 키가 있다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N modeling -e ''SELECT COUNT(DISTINCT referenced_table_name) FROM information_schema.KEY_COLUMN_USAGE WHERE table_schema=\\"modeling\\" AND table_name=\\"enrollments\\" AND referenced_table_name IN (\\"students\\",\\"courses\\")'')\\" = 2 ]"]}, {"label": "두 열 묶음이 기본키다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N modeling -e ''SELECT COUNT(*) FROM information_schema.KEY_COLUMN_USAGE WHERE table_schema=\\"modeling\\" AND table_name=\\"enrollments\\" AND constraint_name=\\"PRIMARY\\"'')\\" = 2 ]"]}, {"label": "수강 기록이 3건 이상이다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N modeling -e ''SELECT COUNT(*) FROM enrollments'')\\" -ge 3 ]"]}]', '[{"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 525 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 525, 11, '연결 테이블로 학생별 강의 보기', '`modeling` 데이터베이스(`mariadb modeling`)를 씁니다. `students`, `courses`, 연결 테이블 `enrollments` 가 있습니다. **학생 이름과 수강 중인 강의 이름**을 한 줄에 하나씩 `/tmp/enroll.txt` 에 저장하세요(제목 줄 없이). 연결 테이블을 가운데 두고 **JOIN 두 번**으로 잇습니다.', '`FROM enrollments e JOIN students s ON ... JOIN courses c ON ...` 처럼 연결 테이블에서 양쪽으로 뻗어 갑니다. 열은 `s.name, c.title` 입니다.', 'mariadb -N modeling -e ''SELECT s.name, c.title FROM enrollments e JOIN students s ON e.student_id = s.id JOIN courses c ON e.course_id = c.id'' > /tmp/enroll.txt
cat /tmp/enroll.txt

# N:M 조회 = 연결 테이블에서 양쪽 테이블로 JOIN 두 번', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS modeling; CREATE DATABASE modeling;''; mariadb modeling -e ''CREATE TABLE students (id INT PRIMARY KEY, name VARCHAR(20)); INSERT INTO students VALUES (1,\\"kim\\"),(2,\\"lee\\"); CREATE TABLE courses (id INT PRIMARY KEY, title VARCHAR(30)); INSERT INTO courses VALUES (1,\\"sql\\"),(2,\\"linux\\"); CREATE TABLE enrollments (student_id INT, course_id INT, PRIMARY KEY (student_id, course_id), FOREIGN KEY (student_id) REFERENCES students(id), FOREIGN KEY (course_id) REFERENCES courses(id)); INSERT INTO enrollments VALUES (1,1),(1,2),(2,1);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(grep -c . /tmp/enroll.txt)\\" = 3 ] ) && ( awk -F\\"\\\\t\\" ''$1==\\"kim\\" && $2==\\"linux\\"'' /tmp/enroll.txt | grep -q . ) && ( [ \\"$(awk -F\\"\\\\t\\" ''$1==\\"lee\\"'' /tmp/enroll.txt)\\" = \\"$(printf \\"lee\\\\tsql\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "3줄이다", "cmd": ["sh", "-c", "[ \\"$(grep -c . /tmp/enroll.txt)\\" = 3 ]"]}, {"label": "kim 은 linux 를 듣는다", "cmd": ["sh", "-c", "awk -F\\"\\\\t\\" ''$1==\\"kim\\" && $2==\\"linux\\"'' /tmp/enroll.txt | grep -q ."]}, {"label": "lee 는 sql 만 듣는다", "cmd": ["sh", "-c", "[ \\"$(awk -F\\"\\\\t\\" ''$1==\\"lee\\"'' /tmp/enroll.txt)\\" = \\"$(printf \\"lee\\\\tsql\\")\\" ]"]}]', '[{"title": "MariaDB 외래 키", "url": "https://mariadb.com/kb/en/foreign-keys/"}, {"title": "MariaDB CREATE TABLE", "url": "https://mariadb.com/kb/en/create-table/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 525 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 525, 12, '텍스트 ERD 읽기', 'ERD 는 테이블 사이의 관계를 그린 그림이고, 텍스트로는 아래처럼 적기도 합니다. `||` 는 "정확히 하나", `o{` 는 "0개 이상 여러 개" 를 뜻합니다. 양쪽이 모두 `{` 로 끝나면 양쪽이 여러 개입니다.

```
customers ||--o{ orders   : places
students  }o--o{ courses  : enrolls
```

이 ERD 에 대한 설명으로 맞는 것은 무엇일까요?', '`||` 쪽은 하나, `{` 쪽은 여러 개입니다.', NULL, NULL, '[]', 'choice', '["고객과 주문은 N:M 이라 연결 테이블이 필요하다", "학생과 강의는 1:N 이라 `courses` 에 FK 를 두면 된다", "두 관계 모두 1:1 이라 한 테이블로 합쳐야 한다", "고객과 주문은 1:N 이라 `orders` 에 FK 를 두고, 학생과 강의는 N:M 이라 연결 테이블이 필요하다"]', 3, '`customers ||--o{ orders` 는 고객 하나에 주문 여러 건(1:N)이고, `students }o--o{ courses` 는 양쪽 모두 여러 개(N:M)입니다. 1:N 은 N 쪽에 FK, N:M 은 연결 테이블로 풉니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 525 AND order_index = 12);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 525, 13, '모델링에서 테이블 만들기까지', '관계가 있는 테이블을 설계해서 만드는 흐름입니다. 업무를 파악해 **가장 먼저 할 일부터 가장 나중 할 일** 순으로 놓으세요. 이 문제에서는 각 테이블의 열과 기본키를 먼저 정한 뒤 관계를 판단합니다.', '각 단계는 앞 단계의 결과를 입력으로 씁니다. 외래 키는 부모의 기본키가 정해져야 걸 수 있습니다.', NULL, NULL, '[]', 'order', '["관계가 1:N 이면 N 쪽에 FK 를, N:M 이면 연결 테이블을 정한다", "테이블마다 속성(열)과 기본키를 정한다", "관리할 대상(엔티티)을 찾는다", "부모 테이블부터 `CREATE TABLE` 로 만들고 `INSERT`·`JOIN` 으로 확인한다", "엔티티 사이의 관계가 1:N 인지 N:M 인지 판단한다"]', NULL, '엔티티 찾기 → 속성·PK 정하기 → 관계 판단 → FK/연결 테이블 결정 → 만들기 순서입니다. 외래 키는 부모 테이블이 먼저 있어야 걸 수 있으므로 부모부터 만듭니다.', '[2, 1, 4, 0, 3]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 525 AND order_index = 13);
